export function compressionOptions() {
  // Force JPEG: the original is only ever shown as a photo (no transparency
  // needed), and it keeps the stored bytes in sync with the "image/jpeg"
  // content-type we upload it under.
  return {
    maxSizeMB: 0.5,
    maxWidthOrHeight: 1280,
    useWebWorker: true,
    fileType: "image/jpeg",
  };
}
===== item-card =====
import Link from "next/link";
import { Surface } from "@/components/ui-fitcheck/surface";

export function ItemCard({
  id,
  name,
  brand,
  imageUrl,
  height,
}: {
  id: string;
  name: string;
  brand?: string | null;
  imageUrl: string;
  height: number;
}) {
  return (
    <Link href={`/closet/${id}`} className="mb-3 block break-inside-avoid">
      <Surface className="overflow-hidden">
        {/* No fill of its own — the cutout floats on the card's gradient, as in
            the design (Fitcheck.dc.html:181, where this div carries only the
            image). A flat panel here covered most of that gradient. */}
        <div style={{ height }}>
          {imageUrl ? (
            // Not next/image on purpose: `imageUrl` is a short-lived signed
            // Supabase URL, and the optimizer caches by URL — a rotating
            // signature means a paid transformation on nearly every view for an
            // image already compressed at upload. Lazy + async decode are the
            // parts of next/image worth having here, and they cost nothing.
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={imageUrl}
              alt={name}
              loading="lazy"
              decoding="async"
              className="size-full object-contain p-5"
            />
          ) : null}
        </div>
        <div className="px-3 pb-3 pt-2">
          {brand && (
            <p className="text-[11px] uppercase tracking-[0.14em] text-muted-dim">
              {brand}
            </p>
          )}
          {/* --color-value (#cfc8ba), the middle of the cream ramp. The design
              gives every label/value pair's VALUE this step; at --foreground it
              read too loud against the brand kicker above it. */}
          <p className="font-serif text-[15px] text-value">{name}</p>
        </div>
      </Surface>
    </Link>
  );
}

