     1	import { test as setup, expect } from "@playwright/test";
     2	import { createClient } from "@supabase/supabase-js";
     3	import { createServerClient } from "@supabase/ssr";
     4	import { seedTestUser, TEST_USER } from "./seed";
     5	
     6	const STORAGE_STATE = "e2e/.auth/state.json";
     7	
     8	/**
     9	 * Sign in once, save the session, and let every other spec start signed in.
    10	 *
    11	 * ⚠️ **The cookie format is produced by `@supabase/ssr` itself, never
    12	 * hand-written.** The session lives in a chunked, base64-encoded cookie whose
    13	 * name is derived from the project URL; reverse-engineering that would work
    14	 * until the library changed it and then fail in a way that looks like an auth
    15	 * bug. Here the library serialises the session into a jar we control, and the
    16	 * exact cookies it emits are handed to Playwright.
    17	 *
    18	 * ⚠️ **Not the magic link.** `/auth/callback` is PKCE and needs a verifier the
    19	 * browser stores when it *initiates* sign-in; a link minted by the admin API
    20	 * has no verifier, so that path cannot be driven from outside the browser.
    21	 * Driving Mailpit's UI instead would be slow and flaky.
    22	 */
    23	setup("authenticate and seed", async ({ browser }) => {
    24	  const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
    25	  const anon = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
    26	  const service = process.env.SUPABASE_SERVICE_ROLE_KEY!;
    27	  expect(url && anon && service, "Supabase env must be sourced before e2e").toBeTruthy();
    28	
    29	  await seedTestUser({ url, service });
    30	
    31	  // A real sign-in, so the session is one Supabase actually issued.
    32	  const { data, error } = await createClient(url, anon).auth.signInWithPassword({
    33	    email: TEST_USER.email,
    34	    password: TEST_USER.password,
    35	  });
    36	  expect(error, `sign-in failed: ${error?.message}`).toBeNull();
    37	  const session = data.session!;
    38	
    39	  // Let @supabase/ssr write the cookies, and record exactly what it wrote.
    40	  const written: { name: string; value: string }[] = [];
    41	  const ssr = createServerClient(url, anon, {
    42	    cookies: {
    43	      getAll: () => [],
    44	      // Must return void, not the push()'s number — the overload is strict.
    45	      setAll: (all) => {
    46	        written.push(...all);
    47	      },
    48	    },
    49	  });
    50	  await ssr.auth.setSession({
    51	    access_token: session.access_token,
    52	    refresh_token: session.refresh_token,
    53	  });
    54	  expect(written.length, "@supabase/ssr wrote no cookies").toBeGreaterThan(0);
    55	
    56	  const context = await browser.newContext();
    57	  await context.addCookies(
    58	    written.map((c) => ({
    59	      name: c.name,
    60	      value: c.value,
    61	      domain: "127.0.0.1",
    62	      path: "/",
    63	      httpOnly: false,
    64	      secure: false,
    65	      sameSite: "Lax" as const,
    66	    })),
    67	  );
    68	  await context.storageState({ path: STORAGE_STATE });
    69	  await context.close();
    70	});

