- [ ] **Step 3: Implement**

```ts
import { maxWears } from "./rewear";

export type TripDay = { date: string; occasion: string };
export type CapsuleItem = { id: string; category: string };

export type OutfitBuilder = (
  day: TripDay,
  available: CapsuleItem[],
) => { itemIds: string[]; score: number } | null;

export type CapsuleInput = {
  closet: CapsuleItem[];
  days: TripDay[];
  level: number;
  floor: number;
  pinned?: string[];
  excluded?: string[];
  build: OutfitBuilder;
};

export type CapsuleResult = {
  itemIds: string[];
  covered: { day: TripDay; itemIds: string[] }[];
  uncovered: TripDay[];
};

/**
 * Greedy set-cover: repeatedly add the piece that newly covers the most days.
 *
 * ⚠️ This is a SET problem, and that is what makes it new. Everything in
 * `lib/generator/` builds outfits one at a time and independently — run it once
 * per day and you get N unrelated outfits needing ~3N items, which is the exact
 * opposite of packing.
 *
 * ⚠️ A day counts as covered only if its outfit clears `floor`. Without that
 * the solve buys a small suitcase with a bad Wednesday.
 *
 * Set cover is NP-hard in general; greedy is the standard approximation and is
 * more than good enough at wardrobe scale (tens of items, days in single figures).
 */
export function solveCapsule(input: CapsuleInput): CapsuleResult {
  const { closet, days, level, floor, build } = input;
  const excluded = new Set(input.excluded ?? []);
  const eligible = closet.filter((i) => !excluded.has(i.id));

  // Pins are seeded at zero cost — they are in the suitcase either way, so the
  // greedy should choose the rest AROUND them.
  const pinnedIds = new Set((input.pinned ?? []).filter((id) => !excluded.has(id)));
  const chosen: CapsuleItem[] = eligible.filter((i) => pinnedIds.has(i.id));

  const assigned = new Map<string, string[]>();
  const wears = new Map<string, number>();
  const limitFor = (item: CapsuleItem) => maxWears(item.category, level, days.length);

  /** Best outfit for a day from `pool`, honouring per-item wear limits. */
  const outfitFor = (day: TripDay, pool: CapsuleItem[]) => {
    const withCapacity = pool.filter((i) => (wears.get(i.id) ?? 0) < limitFor(i));
    const built = build(day, withCapacity);
    return built && built.score >= floor ? built : null;
  };

  const commit = (day: TripDay, itemIds: string[]) => {
    assigned.set(day.date, itemIds);
    for (const id of itemIds) wears.set(id, (wears.get(id) ?? 0) + 1);
  };

  // Days are processed in order so the result is stable — a stored capsule must
  // not change on a second read.
  const remaining = () => days.filter((d) => !assigned.has(d.date));

  // Seed: whatever the pinned set alone can already dress.
  for (const day of remaining()) {
    const built = outfitFor(day, chosen);
    if (built) commit(day, built.itemIds);
  }

  while (remaining().length > 0) {
    let best: { item: CapsuleItem; gain: number } | null = null;

    for (const candidate of eligible) {
      if (chosen.some((c) => c.id === candidate.id)) continue;

      // Count days this candidate would newly cover. Wear state is snapshotted
      // and restored so trialling a candidate never mutates the real tally.
      const snapshot = new Map(wears);
      const pool = [...chosen, candidate];
      let gain = 0;
      for (const day of remaining()) {
        const built = outfitFor(day, pool);
        if (!built) continue;
        gain += 1;
        for (const id of built.itemIds) wears.set(id, (wears.get(id) ?? 0) + 1);
      }
      wears.clear();
      for (const [k, v] of snapshot) wears.set(k, v);

      if (gain > 0 && (!best || gain > best.gain)) best = { item: candidate, gain };
    }

    // Nothing left can cover another day: the remaining days are the shortfall.
    if (!best) break;

    chosen.push(best.item);
    for (const day of remaining()) {
      const built = outfitFor(day, chosen);
      if (built) commit(day, built.itemIds);
    }
  }

  // Report only pieces actually worn, plus pins — a piece the greedy added and
  // then never used would be dead weight in the suitcase.
  const worn = new Set([...assigned.values()].flat());
  const itemIds = chosen.filter((i) => worn.has(i.id) || pinnedIds.has(i.id)).map((i) => i.id);

  return {
    itemIds,
    covered: days.filter((d) => assigned.has(d.date)).map((d) => ({ day: d, itemIds: assigned.get(d.date)! })),
    uncovered: days.filter((d) => !assigned.has(d.date)),
  };
}
```

